-- 6) ما المقصود بحفظ الضروريات الخمس؟
UPDATE qa_questions SET answer='حفظها يكون بأمرين معًا: مراعاتها من جانب الوجود بما يقيم أركانها ويثبّت قواعدها، ومراعاتها من جانب العدم بما يدرأ عنها الاختلال الواقع أو المتوقَّع. والخمس في تعداد الشاطبي: حفظ الدين، والنفس، والنسل، والمال، والعقل، وهي من كليات مقاصد الشريعة.',
       evidence='قال الشاطبي: «وَالْحِفْظُ لَهَا يَكُونُ بِأَمْرَيْنِ: أَحَدُهُمَا: مَا يُقِيمُ أَرْكَانَهَا وَيُثَبِّتُ قَوَاعِدَهَا، وَذَلِكَ عِبَارَةٌ عَنْ مُرَاعَاتِهَا مِنْ جَانِبِ الْوُجُودِ. وَالثَّانِي: مَا يَدْرَأُ عَنْهَا الِاخْتِلَالَ الْوَاقِعَ أَوِ الْمُتَوَقَّعَ فِيهَا، وَذَلِكَ عِبَارَةٌ عَنْ مُرَاعَاتِهَا مِنْ جَانِبِ الْعَدَمِ» — الموافقات ج٢/ص١٨، ثم قال: «وَمَجْمُوعُ الضَّرُورِيَّاتِ خَمْسَةٌ، وَهِيَ: حِفْظُ الدِّينِ، وَالنَّفْسِ، وَالنَّسْلِ، وَالْمَالِ، وَالْعَقْلِ» (ج٢/ص٢٠).',
       reference='الموافقات للشاطبي، ت مشهور آل سلمان: ج٢/ص١٨ و٢٠ (كتاب المقاصد، النوع الأول) | الكلمات المفتاحية: مقاصد، ضروريات، شريعة',
       source_url='https://shamela.ws/book/11435/676',
       verification_status='verified',
       updated_at=now()
 WHERE id='c9d83533-0d08-4ee6-90aa-1dbd83f7f0f5'
